Q: Localized Ordinal Numbers in Java A: <p>Expanding on the Android specific answer with Kotlin Int extensions and test cases.</p>
<pre><code>/**
 * Formats a number as an ordinal string using the default locale.
 * e.g. 1 -&gt; 1st, 2 -&gt; 2nd, 3 -&gt; 3rd...
 */
fun Int.asOrdinal(): String {
    // API 24+
    if (Build.VERSION.SDK_INT &gt;= Build.VERSION_CODES.N) {
        val formatter = android.icu.text.MessageFormat(&quot;{0,ordinal}&quot;, Locale.getDefault())
        val ordinalValue = formatter.format(arrayOf(this))
        return ordinalValue
    } else {
        return this.asOrdinalEnglish()
    }
}

/**
 * Manually calculates the English ordinal suffix for an integer.
 * Handles negative numbers by placing the ordinal after the absolute value.
 * e.g. 1 -&gt; 1st, 11 -&gt; 11th, 21 -&gt; 21st, -1 -&gt; -1st
 */
private fun Int.asOrdinalEnglish(): String {
    val absoluteValue = kotlin.math.abs(this)

    // exception: numbers ending in 11, 12, or 13 use 'th'
    if (absoluteValue % 100 in 11..13) {
        return &quot;${this}th&quot;
    }

    // generic rules
    val lastDigit = absoluteValue % 10
    val suffix = when (lastDigit) {
        1 -&gt; &quot;st&quot;
        2 -&gt; &quot;nd&quot;
        3 -&gt; &quot;rd&quot;
        else -&gt; &quot;th&quot;
    }

    return &quot;$this$suffix&quot;
}
</code></pre>
<p>Tests:</p>
<pre><code>@RunWith(AndroidJUnit4::class)
class OrdinalTests {
    /**
     * English, Spanish, French, Italian, and German use ordinal postfixes.
     * Indonesian uses ordinal prefixes.
     * To test these cases, change your phone's language and check the output.
     *
     * Note: did not test negative ordinals since they are not commonly used.
     * For negatives, note that MessageFormat uses the Unicode Minus Sign (− or U+2212) 
     * instead of the ASCII hyphen-minus (- or U+002D).
     *
     * https://stackoverflow.com/a/55659083/599535
     */
    @Test
    fun works_as_expected() {
        Assert.assertEquals(&quot;0th&quot;, 0.asOrdinal())
        Assert.assertEquals(&quot;1st&quot;, 1.asOrdinal())
        Assert.assertEquals(&quot;2nd&quot;, 2.asOrdinal())
        Assert.assertEquals(&quot;3rd&quot;, 3.asOrdinal())
        Assert.assertEquals(&quot;4th&quot;, 4.asOrdinal())
        Assert.assertEquals(&quot;10th&quot;, 10.asOrdinal())
        Assert.assertEquals(&quot;11th&quot;, 11.asOrdinal())
        Assert.assertEquals(&quot;12th&quot;, 12.asOrdinal())
        Assert.assertEquals(&quot;13th&quot;, 13.asOrdinal())
        Assert.assertEquals(&quot;14th&quot;, 14.asOrdinal())
        Assert.assertEquals(&quot;15th&quot;, 15.asOrdinal())
        Assert.assertEquals(&quot;20th&quot;, 20.asOrdinal())
        Assert.assertEquals(&quot;21st&quot;, 21.asOrdinal())
        Assert.assertEquals(&quot;22nd&quot;, 22.asOrdinal())
        Assert.assertEquals(&quot;23rd&quot;, 23.asOrdinal())
        Assert.assertEquals(&quot;24th&quot;, 24.asOrdinal())
        Assert.assertEquals(&quot;101st&quot;, 101.asOrdinal())
        Assert.assertEquals(&quot;102nd&quot;, 102.asOrdinal())
        Assert.assertEquals(&quot;103rd&quot;, 103.asOrdinal())
        Assert.assertEquals(&quot;104th&quot;, 104.asOrdinal())
        Assert.assertEquals(&quot;105th&quot;, 105.asOrdinal())
    }
}
</code></pre>

Q: TailwindCSS not working with Vite + React A: <p>I followed the documentation to install tailwind with Vite and React and it didn't work either. Then I added these changes in vite.config.js and it worked.</p>
<pre><code>import { defineConfig } from &quot;vite&quot;;
import react from &quot;@vitejs/plugin-react&quot;;
import tailwindcss from &quot;tailwindcss&quot;;

// https://vitejs.dev/config/
export default defineConfig({
  css: {
    postcss: {
      plugins: [tailwindcss()],
    },
  },
});
</code></pre>
